class TokenBucket:
    def __init__(self, capacity, rate):
        self.cap, self.rate = capacity, rate
        self.tokens, self.last = float(capacity), 0.0   # 初始满桶

    def allow(self, now):
        self.tokens = min(self.cap, self.tokens + self.rate * (now - self.last))
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

    def admit(self, series):
        return [(self.allow(t), round(self.tokens, 3)) for t in series]

import re

EMPTY_RULES = [
    (r"(负责|参与|协助)[^，。]{0,12}$", "动词空话"),
    (r"(深入|熟练|扎实)掌握", "程度形容词"),
    (r"(显著|大幅|极大)地?(提升|优化|改善)", "不可证伪成果"),
]

def audit_bullets(bullets):
    report = []
    for b in bullets:
        hits = [name for pat, name in EMPTY_RULES if re.search(pat, b)]
        checks = {"基线": ("→" in b or "从" in b), "口径": any(k in b for k in ("条", "样本", "天", "周")),
                  "归因": any(k in b for k in ("独立", "重写", "引入")), "对比": ("→" in b or "高于" in b)}
        missing = [k for k, ok in checks.items() if not ok]
        report.append((b, hits, missing))
    return sorted(report, key=lambda r: (-len(r[1]), -len(r[2])))
